import { DataPanel } from "@dreamer/ui-view/data-display";
import type { Column, FormField, Row, SearchField } from "@dreamer/ui-view/data-display";

const NAMES = [
  "Alice",
  "Bob",
  "Carol",
  "David",
  "Eve",
  "Frank",
  "Grace",
  "Heidi",
  "Ivan",
  "Judy",
  "Mallory",
  "Niaj",
  "Olivia",
  "Peggy",
  "Rupert",
  "Sybil",
  "Trent",
  "Victor",
  "Walter",
  "Zoe",
  "Liang",
  "Wei",
  "Mei",
  "Chen",
  "Hao",
];

/** 生成演示用户（可复现） */
function makeDemoRows(n = 25): Row[] {
  return Array.from({ length: n }, (_, i) => ({
    id: String(i + 1),
    name: NAMES[i % NAMES.length] + (i >= NAMES.length ? ` ${i}` : ""),
    email: `${NAMES[i % NAMES.length].toLowerCase()}${i + 1}@example.com`,
    role: ["admin", "editor", "viewer"][i % 3],
    status: i % 4 === 3 ? "disabled" : "active",
    balance: 100 + ((i * 137) % 900) + (i % 7) / 10,
    score: (i * 7) % 100,
    createdAt: new Date(2026, 0, 1 + i, 9, (i * 7) % 60).toISOString(),
    locked: i === 0,
  }));
}


const columns: Column[] = [
  {
    type: "selection",
    disable: (row) => row.id === "4" || row.id === "5", // David、Eve 禁止勾选
  },
  { type: "index" },
  { prop: "name", label: "姓名", sortable: true, inline: "text" },
  { prop: "email", label: "邮箱", sortable: true },
  {
    prop: "role",
    label: "角色",
    type: "tag",
    align: "center",
    options: [
      { value: "admin", label: "管理员", tone: "danger" },
      { value: "editor", label: "编辑", tone: "info" },
      { value: "viewer", label: "访客", tone: "default" },
    ],
  },
  {
    prop: "status",
    label: "状态",
    type: "tag",
    inline: "switch",
    align: "center",
    options: [
      { value: "active", label: "启用", tone: "success" },
      { value: "disabled", label: "停用", tone: "warning" },
    ],
  },
  {
    prop: "balance",
    label: "余额",
    type: "money",
    sortable: true,
    total: true,
    align: "right",
    headerAlign: "center",
  },
  {
    prop: "score",
    label: "积分",
    type: "number",
    sortable: true,
    inline: "number",
    align: "right",
  },
  {
    prop: "createdAt",
    label: "创建时间",
    type: "datetime",
    format: "YYYY-MM-DD HH:mm",
    sortable: true,
    hidden: true,
  },
  { type: "actions", actions: {
    view: true,
    edit: true,
    remove: false,
  } },
];

const search: SearchField[] = [
  {
    prop: "name",
    placeholder: "姓名关键字",
    hint: "支持模糊匹配",
    maxlength: 40,
  },
  { prop: "role", type: "select" },
  { prop: "status", type: "select" },
];


const form: FormField[] = [
  { prop: "name", required: true, placeholder: "请输入姓名" },
  {
    prop: "email",
    required: true,
    pattern: "^[^@\\s]+@[^@\\s]+$",
  },
  { prop: "role", type: "select", required: true, initial: "viewer" },
  { prop: "balance", type: "number", min: 0, initial: 0 },
  // switch 开／关值从同 prop 列两档 options 继承，无需 onOff
  { prop: "status", type: "switch", initial: "active" },
];


const rows = makeDemoRows(25);

<DataPanel
  panelKey="demo-basic"
  title="用户管理"
  data={rows}
  columns={columns}
  search={{ props: search }}
  form={{ props: form }}
  exportName="users"
/>

