import {
  createRenderEffect,
  createSignal,
  onCleanup,
} from "@dreamer/view";
import { Button } from "@dreamer/ui-view/basic";

export function Demo() {
  const dynamicPercent = createSignal(0);
  const replayKey = createSignal(0);

  createRenderEffect(() => {
    void replayKey.value;
    dynamicPercent.value = 0;
    const id = globalThis.setInterval(() => {
      const p = dynamicPercent.value;
      if (p >= 100) {
        globalThis.clearInterval(id);
        return;
      }
      dynamicPercent.value = p + 1;
    }, 40);
    onCleanup(() => globalThis.clearInterval(id));
  });

  return (
    <>
      <div class="w-full">
        <Button
          type="button"
          onClick={() => {
            replayKey.value += 1;
          }}
        >
          重新播放
        </Button>
      </div>
      <div class="w-full min-h-9 flex items-center">
        <Progress percent={dynamicPercent} status="active" />
      </div>
      <div class="flex justify-center">
        <Progress
          type="circle"
          percent={dynamicPercent}
          status="active"
          size={100}
        />
      </div>
    </>
  );
}

